func TestAccountAPIKeyOmitsDefaultStore(t *testing.T) {
	var calls int
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		calls++
		if r.Header.Get("Authorization") != "Bearer account-key" {
			t.Error("missing API key")
		}
		expectedStore := ""
		if r.URL.Path == "/v2/products" {
			expectedStore = "configured-store"
		}
		if r.Header.Get("X-STORE") != expectedStore {
			t.Errorf("unexpected store for %s: %q", r.URL.Path, r.Header.Get("X-STORE"))
		}
		io.WriteString(w, "{}")
	}))
	defer server.Close()
	client := NewClient("account-key", "configured-store", WithBaseURL(server.URL), WithMaxRetries(0))
	for _, path := range []string{"/v2/me", "/v2/stores", "/v2/stores/12", "/v2/products"} {
		_, err := client.request(context.Background(), http.MethodGet, path, nil, nil, nil, nil)
		if err != nil {
			t.Fatal(err)
		}
	}
	if calls != 4 {
		t.Fatalf("requests: %d", calls)
	}
}

